'use client';

/**
 * Official ORYX brand lockup for the customer site.
 *
 * Mirrors the admin component: the owner-supplied artwork is one raster lockup,
 * and the source JPEG has no alpha channel, so two colourways are generated by
 * `.run/gen-brand.cjs` and swapped by CSS on `data-theme`.
 */

const RATIO = 1404 / 320;

export function BrandLogo({ height = 30 }: { height?: number }) {
  const width = Math.round(height * RATIO);
  return (
    <span className="oryx-brand-logo" style={{ height, width }}>
      <img
        src="/brand/oryx-logo-on-dark.png"
        alt="ORYX"
        className="oryx-brand-logo__on-dark"
        height={height}
        width={width}
        decoding="async"
      />
      <img
        src="/brand/oryx-logo-on-light.png"
        alt=""
        aria-hidden="true"
        className="oryx-brand-logo__on-light"
        height={height}
        width={width}
        decoding="async"
      />
    </span>
  );
}
